import sys

def main():
    data = sys.stdin.readline().strip()
    if not data:
        return
    parts = data.split()
    if len(parts) < 2:
        print('no')
        return
    s1 = parts[0]
    s2 = parts[1]

    # Manually compare each character (case-sensitive)
    if len(s1) != len(s2):
        print('no')
        return

    equal = True
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            equal = False
            break

    print('yes' if equal else 'no')

if __name__ == '__main__':
    main()
